/* Texte von Spiel 5 „Fahrlehrer-Simulator“ in allen 18 Sprachen (07.10.2026).
   Eigene Datei, damit spiele/texte.js nicht weiter wächst: der Hauptagent führt TEXTE_FAHRLEHRER beim Einbau in TEXTE zusammen
   (Object.assign je Sprache). Schlüssel mit Präfix `fl`.
   Aufbau je Szenario nn (01–14):  flSnn = Bildbeschreibung (auch für Screenreader),
     flSnne1/e2/e3 = Antworten auf „Was hat der Fahrschüler falsch gemacht?“ (e1 ist die RICHTIGE, die Reihenfolge wird im Spiel gemischt),
     flSnnk1/k2/k3 = Antworten auf „Was sagst du als Fahrlehrer?“ (k1 ist die RICHTIGE), flSnnx = Regel/Begründung.
   Einheiten (km/h, m) bleiben lateinisch; Platzhalter {n} {m} müssen in jeder Sprache stehen.
   Quellen der Fachaussagen: StVO (gesetze-im-internet.de/stvo_2013): § 3 Abs. 1 (Geschwindigkeit anpassen), § 3 Abs. 2a (Kinder: Geschwindigkeit verringern, bremsbereit), § 4 Abs. 1 (Abstand), § 8 Abs. 2 (Stoppschild: vorsichtig vortasten, ggf. erneut halten),
   § 5 Abs. 2, Abs. 3 Nr. 1, Abs. 4 (Überholen, Seitenabstand 1,5 m innerorts / 2 m außerorts), § 7 Abs. 4 (Reißverschluss) und Abs. 5 (Fahrstreifenwechsel),
   § 9 Abs. 1 und 3 (Abbiegen, Radfahrer durchlassen), § 11 Abs. 2 (Rettungsgasse), § 14 Abs. 1 (Ein-/Aussteigen), § 17 Abs. 2 (Fernlicht abblenden),
   § 26 Abs. 1 und 3 (Zebrastreifen), Anlage 2 Zeichen 206 (Halt! Vorfahrt gewähren), Zeichen 274.1 (Tempo 30-Zone).
   Fahrschul-Praxis (keine Gesetzesworte): Schulterblick/toter Winkel, „halber Tacho“ als Faustformel für den Abstand, holländischer Griff.
   NICHT von Muttersprachlern geprüft: rif (besonders unsicher), ckb, kmr, ps, am, ti; bitte gegenlesen lassen. */
