    flS03x: "فاصلہ اتنا ہونا چاہیے کہ آگے والی گاڑی اچانک بریک لگائے تو آپ اس کے پیچھے رک سکیں (§ 4 StVO)۔ موٹا اصول: میٹر میں فاصلہ کم از کم km/h میں رفتار کا آدھا ہو، یعنی 100 km/h پر کم از کم 50 m۔ گیلی سڑک پر اس سے زیادہ چاہیے۔",
