    flS04k3: "سڑک خالی لگے تو بغیر رکے آہستہ آہستہ نکل جانا۔",
    flS04x: "„رکیں! راستہ دیں“ کا نشان اسٹاپ لائن پر رکنے کا تقاضا کرتا ہے: گاڑی واقعی رکنی چاہیے، چاہے کچھ نہ آ رہا ہو۔ اس کے بعد آپ کو آڑی سڑک کی ٹریفک کو راستہ دینا ہوتا ہے۔ اگر اسٹاپ لائن سے سڑک نظر نہ آئے تو آپ احتیاط سے آگے بڑھتے ہیں اور ضرورت ہو تو ایک بار پھر رکتے ہیں (§ 8 Abs. 2 StVO)۔",
