    flS07e3: "اس نے گاڑی فٹ پاتھ کے کنارے کے بہت پاس کھڑی کی۔",
    flS07k1: "ڈرائیور کا دروازہ دائیں ہاتھ سے کھولنا (ڈچ ریچ): اس طرح دھڑ مڑتا ہے اور نظر پیچھے جاتی ہے۔",
