    flS07k3: "ذرا سا ہارن بجا کر پھر اترنا۔",
    flS07x: "جو اترتا ہے اسے دوسرے سڑک استعمال کرنے والوں کی حفاظت کرنی ہوتی ہے (§ 14 StVO)۔ ڈچ ریچ میں ڈرائیور دروازہ دور والے، دائیں ہاتھ سے کھولتا ہے۔ اس سے وہ خود بخود پیچھے کی طرف مڑ جاتا ہے، سائیکل سواروں کو دیکھ لیتا ہے اور تب ہی کھولتا ہے جب راستہ صاف ہو۔",
