    flNeu: "Điểm cao nhất mới!",
    flBereit: "Chạm vào Bắt đầu. Bạn là giáo viên dạy lái xe và xem một cảnh với học viên của mình. Đầu tiên bạn chọn lỗi, sau đó chọn chỉ dẫn đúng. Có 8 vòng: bạn trả lời đúng càng nhanh thì càng được nhiều điểm. Sau mỗi vòng sẽ hiện quy tắc.",
    flLegende: "Học viên lái chiếc xe màu xanh dương.",
