    flS04x: "د «ودرېږئ! لار ورکړئ» نښه غواړي چې د درېدو په کرښه کې ودرېږئ: موټر باید په رښتیا ودرېږي، حتی که هیڅ نه راځي. وروسته باید د پرې کېدونکې سړک ترافیک ته لار ورکړئ. که له درېدو کرښې سړک نه وینئ، په احتیاط مخکې ځئ او که اړتیا وي یو ځل بیا ودرېږئ (§ 8 Abs. 2 StVO).",
