    flS05x: "د پیاده تېرېدو په ځای کې باید موټرونه هغو پیاده ته اجازه ورکړي چې په څرګنده غواړي سړک تېر کړي. بیا تاسو یوازې په منځنۍ سرعت نژدې کېږئ او که اړتیا وي، انتظار باسئ (§ 26 StVO). د پیاده تېرېدو ځای مخکې او پر هغه باندې مخکې کېدل نه شئ کولی.",
